dict(no=20, sec="rom", ic="👋", t="米利都告别", ref="徒20:1-38", kw="米利都", kv="徒20:28",
 core="保罗经马其顿、希腊回程，在特罗亚擘饼时使犹推古复活；在米利都向以弗所长老告别：把神的旨意都传给你们，要牧养神用自己血买来的教会。",
 date="约主后 56–57 年（往耶路撒冷，赶五旬节）", place="马其顿、希腊（哥林多）→ 特罗亚 → 米利都", who="保罗、同行的各教会代表、犹推古、以弗所的长老", map=["troas","miletus","ephesus","corinth","philippi"], route=["ephesus","troas","philippi","thessalonica","berea","corinth","berea","thessalonica","philippi","troas","assos","miletus"],
 story="暴动之后，保罗往马其顿，劝勉门徒，再到希腊住了三个月（期间在哥林多写**罗马书**）。各教会代表陪他带捐项上耶路撒冷（{{徒20:4}}）。在特罗亚，**七日的第一日**，门徒聚会擘饼，保罗讲论到半夜，少年人犹推古困倦从三层楼掉下去死了，保罗下去伏在他身上，他就活了（{{徒20:7-12}}）。保罗急着在五旬节赶到耶路撒冷，在米利都请**以弗所教会的长老**来，作了他在使徒行传中唯一一篇对信徒（而非对外人）的讲话：我在你们中间，凡与你们有益的，没有一样避讳不说；**神的旨意我并没有一样避讳不传给你们**（{{徒20:20,27}}）；圣灵在各城向我指证有捆锁与患难等待我，我却不以性命为念（{{徒20:24}}）。**圣灵立你们作全群的监督，你们就当……牧养神的教会**（{{徒20:28}}）；我走了以后，必有凶暴的豺狼进入你们中间，就是你们中间也必有人起来说悖谬的话。我把你们交托神和他恩惠的道（{{徒20:32}}）。施比受更为有福。众人痛哭，送他上船。",
 ol=[("20:1-6","马其顿、希腊：同行的代表"),("20:7-12","七日的第一日：擘饼 · 犹推古"),("20:13-27","米利都讲话（上）：无一避讳"),("20:28-38","米利都讲话（下）：牧养神的教会")],
 bg="捐项是保罗多年为耶路撒冷穷困圣徒向外邦教会募集的（{{罗15:25-27}}；{{林后8–9}}），各教会派代表同行，以示财务透明，也象征外邦与犹太教会的合一。古代船只多在白天沿海岸短程航行，故沿途停靠多港。米利都距以弗所约 50 公里。",
 why=["捐项与合一的使命","要赶五旬节到耶路撒冷","预感一去不返","把教会交给长老与神的道"], res="长老们被托付牧养；保罗踏上往耶路撒冷、终至罗马的路",
 bt="米利都讲话像**旧约领袖的告别演说**：摩西（申命记）、约书亚（{{书23–24}}）、撒母耳（{{撒上12}}）——都回顾忠心、警戒将来、把百姓交托神。也像耶稣在楼上的告别（{{约13–17}}）。“七日的第一日”聚会擘饼，显示**主日已成为新约教会的聚会日**。",
 ct="“牧养神的教会，就是他用自己血所买来的”（{{徒20:28}}）——这是新约中最强烈的**代赎与教会论**连结：基督的血是新约的血（{{路22:20}}），祂所买赎的是一个确定的群体——教会。",
 rf="这是改革宗**长老职分与教会论**的核心经文：①20:17 称“长老”，20:28 称“监督”——**长老与监督是同一职分**（不是三级圣品）；②长老由**圣灵所立**，透过教会选立；③长老的工作是**牧养、谨慎、警醒**防备异端；④教会是基督用血买来的，与多特信经第二项教义“有效救赎”一致（基督为祂的羊舍命，{{约10:11}}）。“神的旨意，我并没有一样避讳不传给你们的”：**全备的讲道**（比利时信条第 7 条：圣经中包含了神全部的旨意）。",
 hard=[("“神用自己血”是说父神有血吗？","这是**属性相通**（communicatio idiomatum）的说法：基督是一个位格，兼有神性与人性；凡属于任一性情的，都可以归于这一个位格。所以可以说“神的血”，指的是那位是神的基督所流的血（参亚他那修信经：基督「不是二位，而是一位基督」）。")],
 conf=[("dort",5,14),("w","wcf",8,1)],
 app=["教会领袖第一要为自己谨慎，然后为全群谨慎（{{徒20:28}}）。","不要只讲受欢迎的部分：把“神的旨意”全部传讲出来。"],
 mn="👋 米利都告别：一个没避讳、两个谨慎（自己与全群）、三个警告（豺狼、悖谬、警醒）、一句话（施比受更为有福）。"),
dict(no=21, sec="rom", ic="⛓️", t="耶路撒冷被捕", ref="徒21:1-40", kw="被捕", kv="徒21:13",
 core="保罗明知捆锁在前仍上耶路撒冷；为平息误会参与洁净礼，却在圣殿被诬带外邦人入殿，几乎被打死，被罗马千夫长救出拘捕。",
 date="主后 57 年五旬节前后", place="推罗、多利买、凯撒利亚 → 耶路撒冷（圣殿、安东尼堡）", who="保罗、腓利与四个说预言的女儿、亚迦布、雅各与长老、千夫长革老丢·吕西亚", map=["tyre","caesarea","jerusalem"], route=["miletus","cos","rhodes","patara","tyre","ptolemais","caesarea","jerusalem"],
 story="保罗乘船经哥士、罗底、帕大喇，在推罗门徒“被圣灵感动”劝他不要上耶路撒冷；在凯撒利亚，住在传福音的**腓利**家（8 章那位），先知**亚迦布**用保罗的腰带捆住自己手脚，预言他要在耶路撒冷被捆绑交在外邦人手里。众人苦劝，保罗说：**我为主耶稣的名，不但被人捆绑，就是死在耶路撒冷也是愿意的**（{{徒21:13}}）。众人便说：愿主的旨意成就吧！在耶路撒冷，雅各和长老欢喜接待，但说有成千上万热心律法的犹太信徒听说保罗教人离弃摩西，建议他与四个许愿的人一同行洁净礼。七日将完，从亚细亚来的犹太人看见他在殿里，就耸动众人，诬告他**带希腊人进殿**，污秽了圣地（{{徒21:28}}）。众人拉他出殿要杀他，千夫长带兵跑下来救出他，用两条铁链捆锁。在营楼台阶上，保罗请求向百姓说话。",
 ol=[("21:1-16","一路警告 · 愿主的旨意成就"),("21:17-26","雅各的建议：洁净礼"),("21:27-36","圣殿暴动 · 被捕"),("21:37-40","营楼台阶上：请准说话")],
 bg="圣殿外邦人院与内院之间有石栏，刻着希腊文与拉丁文警告：外邦人越过此界者自负死罪（考古已发现两块该铭文）。[[安东尼堡]]是紧靠圣殿西北角的罗马营楼，有台阶直通殿院，罗马驻军可迅速镇压节期骚乱。千夫长统领约一千人。当时犹太民族主义高涨，“埃及人”假先知领四千刺客（Sicarii）起事（{{徒21:38}}，约瑟夫亦有记载）。",
 why=["保罗定意带捐项上耶路撒冷","犹太信徒对他存误解","参与洁净礼表明他不反对律法本身","亚细亚犹太人诬告 → 暴动"], res="保罗被罗马拘押，从此以囚犯身份见证，直到罗马",
 bt="保罗的路线刻意对照**耶稣上耶路撒冷**：定意前往（{{路9:51}}）、预言被交在外邦人手里（{{路18:32}}）、“愿主的旨意成就”（参 {{路22:42}}）、群众喊“除掉他”（{{徒21:36}}；参 {{路23:18}}）。**仆人走主人的路**。",
 ct="保罗没有教导犹太信徒放弃割礼与习俗（作为文化与见证），只是反对把它们当作称义的条件。旧约礼仪律在基督里成全，**在过渡期可作为不涉良心的自由**，但不可强加于外邦人（21:25 重申会议决定）。",
 rf="推罗门徒“被圣灵感动”劝阻保罗，与保罗“被圣灵催逼”前往（{{徒20:22}}）并不矛盾：圣灵启示的是**将有捆锁**这一事实，门徒出于爱心的推论是“不要去”，保罗的回应是“为主名愿意”。这说明**预言的恩赐需要被分辨与解释**（{{帖前5:20-21}}）。海德堡要理问答第 1 问：我的身体和灵魂都不属于我自己——保罗以此面对捆锁。",
 hard=[("保罗参与洁净礼是不是妥协？","不是。保罗原则是“向犹太人，我就作犹太人”（{{林前9:20}}），在不涉福音核心与良心的事上为合一让步。他从未说割礼或洁净礼能使人称义；会议已确认外邦人的自由（21:25）。")],
 conf=[("hc",1)],
 app=["顺服神的旨意常意味着走向十字架：“愿主的旨意成就”。","为了合一，在非本质的事上愿意让步，在福音核心上绝不退让。"],
 mn="⛓️ 腰带预言、四人洁净、殿中被捕：“死在耶路撒冷也是愿意的”（21:13）。"),
